  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  if (!inventoryIds.has(value.id)) return null;
  const startedAt = Number(value.startedAt);
  if (!Number.isFinite(startedAt) || startedAt < 0) return null;
