  const target = join(directory, BACKGROUND_AGENT_LIST_INDEX_FILE);
  try {
    const stat = lstatSync(target);
    if (
      !stat.isFile() ||
      stat.isSymbolicLink() ||
      stat.size <= 0 ||
      stat.size > MAX_INDEX_BYTES
    ) {
      return null;
    }
    const parsed = JSON.parse(readFileSync(target, "utf8"));
