  const target = join(directory, BACKGROUND_AGENT_LIST_INDEX_FILE);
  const value = {
    schema: BACKGROUND_AGENT_LIST_INDEX_SCHEMA,
    inventoryDigest: inventory.digest,
    fileCount: inventory.files.length,
    entries,
  };
